import argparse, json, socket
from datetime import datetime

PORTAS = (21, 22, 25, 53, 80, 110, 143, 443, 3000, 3306, 5432, 8000, 8080)

def resolver(alvo):
    try:
        return socket.gethostbyname(alvo)
    except socket.gaierror:
        return None

def portas_abertas(ip, espera=0.3):
    abertas = []
    for porta in PORTAS:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(espera)
            if s.connect_ex((ip, porta)) == 0:
                abertas.append(porta)
    return abertas

def main():
    p = argparse.ArgumentParser(description="Recon básico. Só em alvo próprio ou autorizado.")
    p.add_argument("alvo")
    p.add_argument("--autorizado", action="store_true",
                   help="confirma que você tem autorização por escrito pra testar este alvo")
    args = p.parse_args(["127.0.0.1", "--autorizado"])   # tire isto pra usar de verdade

    if not args.autorizado:
        p.error("sem --autorizado a ferramenta não roda. Escopo primeiro, sempre.")

    ip = resolver(args.alvo)
    if not ip:
        print(f"{args.alvo}: não resolveu")
        return

    relatorio = {
        "alvo": args.alvo,
        "ip": ip,
        "quando": datetime.now().isoformat(timespec="seconds"),
        "abertas": portas_abertas(ip),
    }
    print(json.dumps(relatorio, indent=2))

main()
